import{c as e,Q as i,j as o,m as a}from"./chunks/framework.g_l1frA7.js";const u=JSON.parse('{"title":"Importing Your Data","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/importing-data.md","filePath":"getting-started/importing-data.md","lastUpdated":null}'),r={name:"getting-started/importing-data.md"};function n(s,t,d,l,c,p){return i(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="importing-your-data" tabindex="-1">Importing Your Data <a class="header-anchor" href="#importing-your-data" aria-label="Permalink to &quot;Importing Your Data&quot;">​</a></h1><p>FinSight imports from CSV and from SimpleFIN. Both paths keep your server as the writer — nothing is pushed to a cloud ledger.</p><h2 id="csv-import" tabindex="-1">CSV import <a class="header-anchor" href="#csv-import" aria-label="Permalink to &quot;CSV import&quot;">​</a></h2><p>Supported parsers live in <code>crates/finsight-providers</code>. Supported formats include common bank/credit CSV exports with columns for date, description, and amount.</p><ol><li>Go to <strong>Accounts</strong> and open the CSV import drawer, or use the onboarding importer.</li><li>Upload one or more CSV files. FinSight parses them in <code>crates/finsight-providers</code> and stages <code>import_candidates</code>.</li><li>Review the candidate list: merchant normalization, duplicate detection (same date/amount/description within tolerance), and fee handling are applied.</li><li>Confirm to finalize — staged rows become transactions. Re-importing the same file is deduplicated.</li></ol><p>Files are staged under <code>users/&lt;uuid&gt;/imports/</code> (authenticated, per-user). You can export your data again from <strong>Settings → Data</strong>.</p><h3 id="troubleshooting-csv" tabindex="-1">Troubleshooting CSV <a class="header-anchor" href="#troubleshooting-csv" aria-label="Permalink to &quot;Troubleshooting CSV&quot;">​</a></h3><ul><li><strong>Wrong amount sign?</strong> Some banks export credits as negative — flip the sign mapping in the import preview.</li><li><strong>Duplicate transactions?</strong> FinSight skips exact duplicates within a short window; adjust the account if you see over-merging.</li><li><strong>Unconverted currencies?</strong> Holdings in a foreign currency without a known rate are surfaced separately rather than invented.</li></ul><h2 id="simplefin" tabindex="-1">SimpleFIN <a class="header-anchor" href="#simplefin" aria-label="Permalink to &quot;SimpleFIN&quot;">​</a></h2><p>SimpleFIN Bridge connects your bank to FinSight without storing your bank password on your server — you exchange a SimpleFIN access URL.</p><ol><li>Obtain a SimpleFIN access URL from your bridge.</li><li>Paste it at <strong>Onboarding</strong> or <strong>Accounts → Connect SimpleFIN</strong>.</li><li>FinSight stores the URL inside your encrypted <code>data.sqlcipher</code>, per user, and uses it only when you press <strong>Synchronize</strong>.</li><li>Sync runs fetch accounts and transactions and merge them; the sync run history shows what was pulled.</li></ol><p>You can remove the access URL at any time — synchronization stops, existing imported transactions remain.</p><h2 id="after-import" tabindex="-1">After import <a class="header-anchor" href="#after-import" aria-label="Permalink to &quot;After import&quot;">​</a></h2><ul><li><strong>Review queue</strong> — uncategorized or low-confidence transactions land in <strong>Insights → Needs Review</strong> and <strong>Transactions → Review</strong>.</li><li><strong>Categorization</strong> — an LLM provider (if configured) proposes categories; deterministic rules and keyword fallbacks apply otherwise. See <a href="/FinSight/automation/categorization">Categorization</a>.</li><li><strong>Balance history &amp; net worth</strong> — derived by <code>finsight-core</code> from transactions and stored balances; no manual double-entry.</li></ul><p>Next: <a href="/FinSight/getting-started/configuring-ai">Configuring AI</a>.</p>',15)])])}const h=e(r,[["render",n]]);export{u as __pageData,h as default};
